vulnerable_code:
app.delete('/api/profile/remove', async (req, res) => {
  const targetId = req.headers['x-target-id'];
  await Profile.deleteOne({ _id: targetId });
  res.send('Deleted');
});

corrected_code:
app.delete('/api/profile/remove', async (req, res) => {
  const targetId = req.headers['x-target-id'];
  await Profile.deleteOne({ _id: targetId, user: req.auth.id });
  res.send('Deleted');
});
